// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}
return $input.all();

// Extract letter answer + question ID from reply email
const email = $input.first().json;
const body = (email.snippet || email.text || '').toString();
const subject = email.subject || email.Subject || '';

const answerMatch = body.match(/\b[ABCD]\b/i);
const userAnswer = answerMatch ? answerMatch[0].toUpperCase() : null;

// Try to pull subject name out of the original subject line: "NDA Mock Test [Math] - ..."
const subjectTagMatch = subject.match(/\[(.*?)\]/);
const subjectTag = subjectTagMatch ? subjectTagMatch[1] : 'Unknown';

return {
  userAnswer,
  subjectTag,
  rawSubjectLine: subject,
  receivedAt: new Date().toISOString()
};

// Compare user answer to correct answer stored in matched Notion page
const matched = $input.first().json;
const userAnswer = $('Parse Answer from Reply').item.json.userAnswer;
const questionIdText = matched.properties?.QuestionID?.rich_text?.[0]?.plain_text || '';

return {
  notionPageId: matched.id,
  userAnswer,
  questionPageId: questionIdText,
  subject: matched.properties?.Subject?.select?.name || 'Unknown'
};

const correctAnswer = $input.first().json.properties?.Answer?.select?.name || 'A';
const userAnswer = $('Prepare Answer Check').item.json.userAnswer;
const isCorrect = userAnswer === correctAnswer;

return {
  notionPageId: $('Prepare Answer Check').item.json.notionPageId,
  subject: $('Prepare Answer Check').item.json.subject,
  userAnswer,
  correctAnswer,
  isCorrect,
  status: isCorrect ? 'Correct' : 'Incorrect'
};

// ---- WEEKLY ANALYSIS + SPACED REPETITION ----
const perfRecords = $("Fetch All Performance Records").all().map(i => i.json);
const studyPlanRecords = $("Fetch Current Study Plan").all().map(i => i.json);

const focusRecords = $("Fetch Recent Focus Log").all().map(i => i.json);
const caRecords = $("Fetch Recent Current Affairs").all().map(i => i.json);

const totalFocusMinutes = focusRecords.reduce((sum, r) => sum + (r.properties?.Minutes?.number || 0), 0);

const hourTotals = {};
focusRecords.forEach(r => {
  const hour = r.properties?.SessionHour?.rich_text?.[0]?.plain_text || 'Unknown';
  hourTotals[hour] = (hourTotals[hour] || 0) + (r.properties?.Minutes?.number || 0);
});
const bestStudyHour = Object.entries(hourTotals).sort((a, b) => b[1] - a[1])[0]?.[0] || 'N/A';

const currentAffairsCount = caRecords.length;


const subjectStats = {};
perfRecords.forEach(rec => {
  const subject = rec.properties?.Subject?.select?.name || 'Unknown';
  const status = rec.properties?.Status?.select?.name || 'Incorrect';
  if (!subjectStats[subject]) subjectStats[subject] = { correct: 0, total: 0 };
  subjectStats[subject].total++;
  if (status === 'Correct') subjectStats[subject].correct++;
});

const analysis = {};
Object.keys(subjectStats).forEach(s => {
  const stat = subjectStats[s];
  analysis[s] = {
    accuracy: ((stat.correct / stat.total) * 100).toFixed(1),
    correct: stat.correct,
    total: stat.total
  };
});

const weakAreas = Object.entries(analysis)
  .filter(([_, s]) => parseFloat(s.accuracy) < 60)
  .map(([subject]) => subject);

const strongAreas = Object.entries(analysis)
  .filter(([_, s]) => parseFloat(s.accuracy) >= 80)
  .map(([subject]) => subject);

const overallAccuracy = perfRecords.length > 0
  ? ((perfRecords.filter(r => r.properties?.Status?.select?.name === 'Correct').length / perfRecords.length) * 100).toFixed(1)
  : '0';

// Build updated study plan priorities (for each topic, decide new priority + spaced repetition interval)
const updates = studyPlanRecords.map(topic => {
  const subject = topic.properties?.Subject?.select?.name || 'General';
  const isWeak = weakAreas.includes(subject);
  const isStrong = strongAreas.includes(subject);

  let priority = 'NORMAL';
  let reviewInDays = 7;
  if (isWeak) { priority = 'HIGH'; reviewInDays = 1; }
  else if (isStrong) { priority = 'LOW'; reviewInDays = 14; }

  const nextReview = new Date();
  nextReview.setDate(nextReview.getDate() + reviewInDays);

  return {
    pageId: topic.id,
    subject,
    priority,
    nextReviewDate: nextReview.toISOString().split('T')[0]
  };
});

return {
  analysis,
  weakAreas,
  strongAreas,
  overallAccuracy,
  totalTests: perfRecords.length,
  studyPlanUpdates: updates,
  totalFocusMinutes,
  bestStudyHour,
  currentAffairsCount
};

