// Pull the doubt text out of the incoming email
const email = $input.first().json;
const body = (email.text || email.snippet || '').toString();
const subjectLine = email.subject || email.Subject || '';

// Strip the "NDA Doubt:" prefix the student is asked to use
const doubtText = (subjectLine.replace(/NDA Doubt:?/i, '').trim() + ' ' + body).trim();

const stopwords = new Set(['the','is','a','an','of','to','in','on','for','and','or','what','how','why','does','do','i','my','me','it','this','that','with','are','was','were','can','you','please','help','not','understand']);

const keywords = doubtText
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(w => w.length > 2 && !stopwords.has(w));

return {
  doubtText,
  keywords,
  rawSubjectLine: subjectLine,
  receivedAt: new Date().toISOString()
};

// Score every question in the bank against the student's doubt keywords
const doubtKeywords = $('Extract Doubt Text').item.json.keywords;
const questions = $input.all().map(i => i.json);

function scoreQuestion(q) {
  const props = q.properties || {};
  const qText = (props.Question?.title?.[0]?.plain_text || '').toLowerCase();
  const subject = (props.Subject?.select?.name || '').toLowerCase();
  const explanation = (props.Explanation?.rich_text?.[0]?.plain_text || '').toLowerCase();
  const combined = qText + ' ' + subject + ' ' + explanation;
  let score = 0;
  doubtKeywords.forEach(k => { if (combined.includes(k)) score++; });
  return score;
}

let best = null;
let bestScore = 0;
questions.forEach(q => {
  const s = scoreQuestion(q);
  if (s > bestScore) { bestScore = s; best = q; }
});

// Require at least 2 overlapping keywords before we trust the match
const matchFound = best !== null && bestScore >= 2;

if (!matchFound) {
  return { matchFound: false, bestScore };
}

const props = best.properties || {};
return {
  matchFound: true,
  bestScore,
  subject: props.Subject?.select?.name || 'General',
  matchedQuestion: props.Question?.title?.[0]?.plain_text || '',
  explanation: props.Explanation?.rich_text?.[0]?.plain_text || 'No explanation available.',
  videoLink: props.VideoLink?.url || ''
};

// n8n Code Node - Parse Daily Current Affairs text into structured JSON

const input = $input.first().json;

// Auto-detect which field holds the text (adjust priority order if needed)
const inputText =
  input.text ||
  input.output ||
  input.content ||
  input.message?.content ||
  input.data ||
  (typeof input === 'string' ? input : null);

if (!inputText || typeof inputText !== 'string') {
  throw new Error(
    'Could not find a valid text field to parse. Available keys: ' +
    Object.keys(input).join(', ')
  );
}

const lines = inputText.split('\n');

let currentCategory = null;
let items = [];
let currentItem = null;
let stage = null; // 'headline' | 'summary' | 'relevance'
let quickRevisionPoints = [];
let inQuickRevision = false;
let dateLine = '';

const categoryHeadings = [
  'NATIONAL',
  'INTERNATIONAL',
  'ECONOMY AND BUSINESS',
  'SCIENCE AND TECHNOLOGY',
  'SPORTS',
  'AWARDS AND APPOINTMENTS',
  'ENVIRONMENT AND DEFENCE',
  'OBITUARIES',
  'QUICK REVISION POINTS'
];

for (let rawLine of lines) {
  const line = rawLine.trim();

  if (!line) continue; // skip blank lines

  // Capture the date line
  if (line.startsWith('DAILY CURRENT AFFAIRS')) {
    dateLine = line.replace('DAILY CURRENT AFFAIRS - ', '').trim();
    continue;
  }

  // Detect QUICK REVISION POINTS section
  if (line === 'QUICK REVISION POINTS') {
    inQuickRevision = true;
    currentCategory = null;
    continue;
  }

  // Detect category headings
  if (categoryHeadings.includes(line) && line !== 'QUICK REVISION POINTS') {
    currentCategory = line;
    inQuickRevision = false;
    continue;
  }

  // Handle Quick Revision Points
  if (inQuickRevision) {
    if (/^\d+\.$/.test(line)) {
      continue; // number-only line, skip
    }
    quickRevisionPoints.push(line);
    continue;
  }

  // Detect numbered item start (e.g., "1.")
  if (/^\d+\.$/.test(line)) {
    if (currentItem) {
      items.push(currentItem);
    }
    currentItem = {
      category: currentCategory,
      headline: '',
      summary: '',
      relevance: ''
    };
    stage = 'headline';
    continue;
  }

  if (!currentItem) continue;

  // Detect Relevance line
  if (line.startsWith('Relevance:')) {
    currentItem.relevance = line.replace('Relevance:', '').trim();
    stage = 'done';
    continue;
  }

  // Fill headline or summary based on stage
  if (stage === 'headline') {
    currentItem.headline = line;
    stage = 'summary';
  } else if (stage === 'summary') {
    currentItem.summary = currentItem.summary
      ? currentItem.summary + ' ' + line
      : line;
  }
}

// push last item if exists
if (currentItem) {
  items.push(currentItem);
}

return [{
  json: {
    date: dateLine,
    totalItems: items.length,
    items: items,
    quickRevisionPoints: quickRevisionPoints
  }
}];

