// Extract minutes + subject from a focus check-in reply, e.g. "45 Math"
const email = $input.first().json;
const body = (email.text || email.snippet || '').toString();

const match = body.match(/(\d{1,3})\s*(?:min(?:ute)?s?)?\s*([A-Za-z]+)/i);
const minutes = match ? parseInt(match[1], 10) : 0;
const subjectRaw = match ? match[2] : 'General';
const subject = subjectRaw.charAt(0).toUpperCase() + subjectRaw.slice(1).toLowerCase();

const now = new Date();
const sessionHour = now.getHours().toString().padStart(2, '0') + ':00';

return {
  minutes,
  subject,
  sessionHour,
  date: now.toISOString().split('T')[0]
};

function parseNDAQuestion(rawOutput) {
  let cleaned = String(rawOutput).trim();

  // Strip accidental code fences
  cleaned = cleaned.replace(/^```(?:json)?\s*/i, "").replace(/```\s*$/i, "").trim();

  // Fallback: extract first {...} block if extra text sneaks in
  if (!cleaned.startsWith("{")) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) cleaned = match[0];
  }

  let data;
  try {
    data = JSON.parse(cleaned);
  } catch (err) {
    throw new Error(`Failed to parse NDA question JSON: ${err.message}\nRaw output: ${rawOutput}`);
  }

  const requiredFields = ["subject", "topic", "difficulty", "question", "options", "correct_option", "explanation"];
  for (const field of requiredFields) {
    if (!(field in data)) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  const optionKeys = ["A", "B", "C", "D"];
  for (const key of optionKeys) {
    if (!(key in data.options)) {
      throw new Error(`Missing option: ${key}`);
    }
  }

  if (!optionKeys.includes(data.correct_option)) {
    throw new Error(`Invalid correct_option: ${data.correct_option}`);
  }

  return data;
}

// n8n entry point — must return an array of { json: {...} } objects
const rawOutput = $input.first().json.output ?? $input.first().json.text ?? $input.first().json.content;

const parsed = parseNDAQuestion(rawOutput);

return [
  {
    json: parsed
  }
];
